#include <vector>
#include <algorithm>

class Solution {
public:
    int getLastMoment(int n, std::vector<int>& left, std::vector<int>& right) {
        int ans = 0;
        for (int p : left) ans = std::max(ans, p);
        for (int p : right) ans = std::max(ans, n - p);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int getLastMoment(int n, int[] left, int[] right) {
        int ans = 0;
        for (int p : left) ans = Math.max(ans, p);
        for (int p : right) ans = Math.max(ans, n - p);
        return ans;
    }
}

var getLastMoment = function(n, left, right) {
    let ans = 0;
    for (const p of left) ans = Math.max(ans, p);
    for (const p of right) ans = Math.max(ans, n - p);
    return ans;
};
